<script setup lang="ts">
import { defaults } from '#shared/validation'
const { data } = await useWorkspace()
const route = useRoute()
const form = reactive({ name: '', modelId: String(route.query.model || ''), datasetId: '', serverId: '', config: { ...defaults } })
const advanced = ref(false), busy = ref(false), error = ref('')
const model = computed(() => data.value.models.find(x => x.id === form.modelId))
const dataset = computed(() => data.value.datasets.find(x => x.id === form.datasetId))
const server = computed(() => data.value.servers.find(x => x.id === form.serverId))
const ready = computed(() => data.value.models.length && data.value.datasets.length && data.value.servers.length)
if (route.query.clone) {
  const previous = await useRequestFetch()(`/api/runs/${route.query.clone}`).catch(() => null)
  if (previous) Object.assign(form, { name: `${previous.run.name} · iteration`, modelId: previous.run.modelId, datasetId: previous.run.datasetId, serverId: previous.run.serverId, config: { ...previous.run.config, resumeFrom: '' } })
}
async function launch() {
  busy.value = true; error.value = ''
  try { const result = await $fetch('/api/runs', { method: 'POST', body: form }); await refreshNuxtData('workspace'); useNotice().notify('Experiment queued'); await navigateTo(`/runs/${result.id}`) }
  catch (e) { error.value = apiError(e) } finally { busy.value = false }
}
</script>
<template><NuxtLink to="/runs" class="back-link"><AppIcon name="ArrowLeft" :size="16" />Experiments</NuxtLink><div class="page-heading"><div><span class="eyebrow">ONE MORE ITERATION</span><h1>New experiment<span class="title-dot">.</span></h1><p>Choose your ingredients. Set your direction.</p></div><span class="pill recipe-pill"><AppIcon name="AudioLines" :size="15" />Tamil Whisper · LoRA</span></div><div v-if="!ready" class="alert info"><AppIcon name="CircleHelp" /><span>Before launching, add <NuxtLink to="/models">a model</NuxtLink>, <NuxtLink to="/datasets">a dataset</NuxtLink>, and <NuxtLink to="/servers">a compute worker</NuxtLink>.</span></div><form class="training-layout" @submit.prevent="launch"><div class="training-main"><section class="panel form-panel"><div class="form-section-title"><span>01</span><div><h2>The essentials</h2><p>Give this experiment a home and a name.</p></div></div><label class="field">Experiment name<input v-model="form.name" required minlength="2" maxlength="100" placeholder="e.g. Tamil calls · LoRA baseline" /></label><div class="form-grid"><label class="field">Base model<select v-model="form.modelId" required><option value="" disabled>Select a model</option><option v-for="m in data.models" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><label class="field">Dataset<select v-model="form.datasetId" required><option value="" disabled>Select a dataset</option><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{ d.name }}</option></select></label></div><label class="field">Compute worker<select v-model="form.serverId" required><option value="" disabled>Select a server</option><option v-for="s in data.servers" :key="s.id" :value="s.id">{{ s.name }} · {{ isOnline(s) ? 'Online' : 'Offline' }}</option></select></label><div v-if="server && !isOnline(server)" class="inline-note"><AppIcon name="Clock3" :size="16" />This run waits in the queue until the worker connects.</div><div v-if="dataset && dataset.labelOrigin !== 'human'" class="inline-note"><AppIcon name="CircleHelp" :size="16" />Reference labels are not fully human verified.</div></section><section class="panel form-panel"><div class="form-section-title"><span>02</span><div><h2>Training parameters</h2><p>A conservative starting point. Tune it to your data.</p></div></div><div class="form-grid"><label class="field">Learning rate<input v-model.number="form.config.lr" type="number" min="0.0000001" max="0.01" step="any" required /><small>Model change per optimizer update.</small></label><label class="field">Epochs<input v-model.number="form.config.epochs" type="number" min="0.1" max="100" step="0.1" required /><small>Passes through the training dataset.</small></label><label class="field">Batch size<input v-model.number="form.config.batch" type="number" min="1" max="128" required /><small>Examples per GPU step.</small></label><label class="field">Gradient accumulation<input v-model.number="form.config.accum" type="number" min="1" max="128" required /><small>Steps combined before an update.</small></label></div><div class="effective-batch"><AppIcon name="Layers" :size="16" />Effective batch size<strong>{{ form.config.batch * form.config.accum }} examples</strong></div><button type="button" class="advanced-toggle" :aria-expanded="advanced" @click="advanced = !advanced"><AppIcon name="SlidersHorizontal" :size="16" />Advanced settings<AppIcon :name="advanced ? 'ChevronDown' : 'ChevronRight'" :size="16" /></button><div v-if="advanced" class="form-grid advanced-fields"><label class="field">LoRA rank<input v-model.number="form.config.rank" type="number" min="1" max="256" required /></label><label class="field">Data-loader workers<input v-model.number="form.config.workers" type="number" min="0" max="64" required /></label><label class="field">Evaluation fraction<input v-model.number="form.config.evalFrac" type="number" min="0.05" max="0.4" step="0.01" :disabled="dataset?.source === 'huggingface'" /><small>Manifest split keeps speakers separate.</small></label><label class="field">Random seed<input v-model.number="form.config.seed" type="number" min="0" max="2147483647" required /></label><label class="field span-2">Resume checkpoint <span class="optional">optional</span><input v-model="form.config.resumeFrom" placeholder="/forgelabs-runs/previous-run/checkpoint-100" /><small>Must be inside the worker run directory and match the model, data, and configuration. Adapter-only exports cannot resume training.</small></label></div></section></div><aside class="panel launch-summary"><span class="eyebrow">RUN SUMMARY</span><h2>Ready when you are.</h2><dl><div><dt>Recipe</dt><dd>Whisper + LoRA</dd></div><div><dt>Model</dt><dd>{{ model?.name || 'Not selected' }}</dd></div><div><dt>Dataset</dt><dd>{{ dataset?.name || 'Not selected' }}</dd></div><div><dt>Compute</dt><dd>{{ server?.name || 'Not selected' }}</dd></div><div><dt>Precision</dt><dd>BF16</dd></div><div><dt>Checkpoint interval</dt><dd>Every epoch</dd></div></dl><div class="summary-note"><AppIcon name="ShieldCheck" :size="20" /><p>The worker validates the dataset before starting. Closing the browser won’t stop training.</p></div><p v-if="error" class="alert error" role="alert">{{ error }}</p><button class="button primary full" :disabled="busy || !ready"><AppIcon :name="busy ? 'LoaderCircle' : 'Play'" :size="16" />{{ busy ? 'Creating experiment…' : 'Queue experiment' }}</button><small class="form-hint centered">Configuration is saved with every run.</small></aside></form></template>
